export const SocialGlyph = ({ id, className = 'w-5 h-5' }) => {
  const common = { className, viewBox: '0 0 24 24', fill: 'currentColor', 'aria-hidden': true };
  if (id === 'whatsapp') {
    return (
      <svg {...common}>
        <path d="M20.5 3.5A11 11 0 006.3 18.7L3 21l2.4-3.2A11 11 0 1020.5 3.5zm-8.5 16a9 9 0 01-4.6-1.3l-.3-.2-2.7.9.9-2.6-.2-.3A9 9 0 1112 19.5zm5-6.7c-.3-.1-1.6-.8-1.9-.9s-.4-.1-.6.1-.7.9-.8 1-.3.2-.6.1a7.4 7.4 0 01-2.2-1.4 8.2 8.2 0 01-1.5-1.9c-.2-.3 0-.4.1-.6l.4-.5.1-.3a.5.5 0 000-.5c0-.1-.6-1.4-.8-1.9s-.4-.4-.6-.4h-.5a1 1 0 00-.7.3 2.9 2.9 0 00-.9 2.2 5 5 0 001.1 2.6 11.5 11.5 0 004.4 3.9c1.6.7 2.2.8 3 .7a2.5 2.5 0 001.7-1.2 2 2 0 00.1-1.2c-.1-.2-.3-.2-.6-.3z" />
      </svg>
    );
  }
  if (id === 'facebook') {
    return (
      <svg {...common}>
        <path d="M14 9h3V6h-3c-2.2 0-4 1.8-4 4v2H8v3h2v7h3v-7h3l1-3h-4V10c0-.6.4-1 1-1z" />
      </svg>
    );
  }
  if (id === 'instagram') {
    return (
      <svg {...common}>
        <path d="M7 3h10a4 4 0 014 4v10a4 4 0 01-4 4H7a4 4 0 01-4-4V7a4 4 0 014-4zm10 2H7a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2zm-5 3.2A3.8 3.8 0 1112 16.8 3.8 3.8 0 0112 8.2zm0 6.2a2.4 2.4 0 100-4.8 2.4 2.4 0 000 4.8zM17.2 6.5a.9.9 0 11-1.8 0 .9.9 0 011.8 0z" />
      </svg>
    );
  }
  if (id === 'linkedin') {
    return (
      <svg {...common}>
        <path d="M6.5 9H4V20h2.5V9zM5.2 4A1.6 1.6 0 105.2 7.2 1.6 1.6 0 005.2 4zM20 20h-2.5v-5.6c0-1.8-.7-2.4-1.7-2.4s-1.8.9-1.8 2.5V20H11.5V9H14v1.2c.6-.9 1.7-1.5 3-1.5 2.4 0 3 1.6 3 4.6V20z" />
      </svg>
    );
  }
  if (id === 'email') {
    return (
      <svg {...common} fill="none" stroke="currentColor" strokeWidth="1.8">
        <path strokeLinecap="round" strokeLinejoin="round" d="M4 6h16v12H4V6zm0 0l8 7 8-7" />
      </svg>
    );
  }
  if (id === 'phone') {
    return (
      <svg {...common} fill="none" stroke="currentColor" strokeWidth="1.8">
        <path strokeLinecap="round" strokeLinejoin="round" d="M6.5 4.5h3l1.2 3-1.8 1.2a12 12 0 006.4 6.4L16.5 13.3l3 1.2v3A15.5 15.5 0 016.5 4.5z" />
      </svg>
    );
  }
  return null;
};

export const SocialDock = ({ vertical = true, light = false }) => (
  <div className={`social-dock ${vertical ? 'social-dock-vertical' : 'social-dock-row'} ${light ? 'social-dock-light' : ''}`}>
    {SOCIAL_LINKS.map((item, i) => (
      <a
        key={item.id}
        href={item.href}
        target={item.href.startsWith('http') ? '_blank' : undefined}
        rel="noopener noreferrer"
        aria-label={item.label}
        title={`${item.label} · ${item.hint}`}
        className="social-btn"
        style={{ animationDelay: `${0.9 + i * 0.08}s`, '--social': item.color }}
      >
        <SocialGlyph id={item.id} />
        <span className="social-tip">{item.label}</span>
      </a>
    ))}
  </div>
);
