// API Base URL - Use environment variable or default to production backend
export const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://backend.tmfouzy.sg/api';

const REQUEST_TIMEOUT_MS = 30000;

const formatApiError = (errorData) => {
  if (!errorData) return 'Unknown error occurred';
  if (typeof errorData === 'string') return errorData;
  if (errorData.error) return errorData.error;
  if (errorData.detail) return errorData.detail;
  const lines = [];
  Object.entries(errorData).forEach(([field, msgs]) => {
    const label = field === 'non_field_errors' ? '' : `${field}: `;
    const msg = Array.isArray(msgs) ? msgs.join(', ') : String(msgs);
    lines.push(`${label}${msg}`);
  });
  return lines.join('\n') || 'Request failed';
};

const parseJsonSafe = async (response) => {
  const contentType = response.headers.get('content-type') || '';
  const text = await response.text();
  if (!text) return null;
  if (!contentType.includes('application/json')) {
    if (!response.ok) {
      throw new Error(response.status === 404 ? 'Not found' : `Server error (${response.status})`);
    }
    return text;
  }
  try {
    return JSON.parse(text);
  } catch {
    throw new Error('Invalid response from server. Please try again.');
  }
};

export const fetchJson = async (url, options = {}) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), options.timeout || REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    const data = await parseJsonSafe(response);
    if (!response.ok) {
      throw new Error(formatApiError(data) || `Request failed (${response.status})`);
    }
    return data;
  } catch (error) {
    if (error.name === 'AbortError') {
      throw new Error('Request timed out. Please try again.');
    }
    if (error.message === 'Failed to fetch' || error.name === 'TypeError') {
      throw new Error('Unable to connect to the server. Please check your internet connection.');
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
};

